import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJFGRv8Z.js";var i=JSON.parse(`{"title":"域名与邮件投递","description":"","frontmatter":{},"headers":[],"relativePath":"admin/domains-delivery.md","filePath":"admin/domains-delivery.md","lastUpdated":0}`),a={name:`admin/domains-delivery.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="域名与邮件投递" tabindex="-1">域名与邮件投递 <a class="header-anchor" href="#域名与邮件投递" aria-label="Permalink to “域名与邮件投递”">​</a></h1><h2 id="域名上线流程" tabindex="-1">域名上线流程 <a class="header-anchor" href="#域名上线流程" aria-label="Permalink to “域名上线流程”">​</a></h2><ol><li>添加域名并设置用途与归属。</li><li>生成并发布所有权验证记录。</li><li>发布 MX、SPF、DKIM 和 DMARC。</li><li>在后台执行 DNS 健康检查。</li><li>配置收信、发信策略和配额。</li><li>用测试邮箱完成收信、发信与回复验证。</li></ol><p>DNS 页面给出的主机名和记录值是唯一准确信息。轮换 DKIM 时先发布新公钥，确认生效后切换签名，再移除旧记录。</p><h2 id="发信审批" tabindex="-1">发信审批 <a class="header-anchor" href="#发信审批" aria-label="Permalink to “发信审批”">​</a></h2><p>平台可分别控制域名发信资格和用户发信资格。审核时核对用途、预计量级、收件人来源及退订机制。异常批量发送时应先暂停资格，再调查账号和密钥是否泄露。</p><h2 id="投递与抑制" tabindex="-1">投递与抑制 <a class="header-anchor" href="#投递与抑制" aria-label="Permalink to “投递与抑制”">​</a></h2><p>直接 MX 投递依赖服务器身份、DNS、IP 信誉和远端策略；中继投递还依赖供应商凭据和额度。永久失败或多次网络失败的收件人可进入抑制名单，防止持续重试。</p><p>解除抑制前先确认地址已恢复有效。仅清空名单而不处理根因，会再次产生退信并影响信誉。</p><h2 id="rspamd-隔离区" tabindex="-1">rspamd 隔离区 <a class="header-anchor" href="#rspamd-隔离区" aria-label="Permalink to “rspamd 隔离区”">​</a></h2><p>隔离区用于查看被反垃圾策略拦截的邮件。管理员可以释放、删除或协助申诉。释放前检查发件域、认证结果、链接和附件；可疑内容不应投递给用户。</p><h2 id="tls" tabindex="-1">TLS <a class="header-anchor" href="#tls" aria-label="Permalink to “TLS”">​</a></h2><p><code>mail.to9.us</code> 的 IMAPS、POP3S 和 SMTP STARTTLS 应提供有效且主机名匹配的证书。证书更新后，要确认实际邮件服务已经加载新文件，而不只是网页代理更新成功。</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};